async function sweepWorkOpeners(ch){
 const stages=await page.locator('button[data-r-section],button[data-q-section],button[data-d-stage],button[data-l-stage],button[data-a-stage],button[data-t-stage],button[data-tr-stage],button[data-i-stage],button[data-sec-stage],button[data-rt-stage],button[data-rv-stage]').filter({visible:true}).evaluateAll(es=>es.filter(e=>!e.disabled).map(e=>({label:e.textContent.trim(),attributes:Object.fromEntries([...e.attributes].filter(a=>a.name.startsWith('data-')).map(a=>[a.name,a.value]))})));
 const seen=new Set();
 for(const stage of [{label:'initial'},...stages]){
  if(stage.attributes)await pressIf(buttonSelector(stage));
  const inventory=await controls();result.observedButtons.push({chapter:ch,tab:'work',workflow:'work-openers-'+stage.label,controls:inventory});
  const candidates=inventory.filter(c=>c.tag==='BUTTON'&&c.visible&&!c.disabled&&Object.entries(c.attributes).some(([key,value])=>/^data-(r|q|d|l|a|t|tr|i|sec|rt|rv)-action$/.test(key)&&/^(?:new(?:-|$)|edit(?:-|$)|add(?:-|$)|connect$|map$|boundary$|needs$|field$|party$|lineage$|environment$|zone$|placement$|path$|intake$|handoff$|narrative$|action$)/.test(value)));
  for(const candidate of candidates){const key=controlKey(candidate,String(ch),'work');if(seen.has(key))continue;seen.add(key);const selector=buttonSelector(candidate);if(!await page.locator(selector).filter({visible:true}).count())continue;
   await attempt('Open/cancel '+ch+' '+candidate.label,async()=>{await pressIf(selector);const dialogs=page.locator('dialog[open]');if(await dialogs.count()){
    result.observedButtons.push({chapter:ch,tab:'work',workflow:'opened-'+candidate.label,controls:await controls()});
    const steps=page.locator('dialog[open] .l-steps button:visible');const count=await steps.count();for(let i=0;i<count;i++){if(await steps.nth(i).isEnabled()){await steps.nth(i).click();result.observedButtons.push({chapter:ch,tab:'work',workflow:'opened-'+candidate.label+'-step-'+i,controls:await controls()});}}
    await closeDialogs();
   }result.actions.push({type:'inspected-without-save',chapter:ch,action:candidate.label});
   if(new URL(page.url()).searchParams.get('chapter')!==String(ch)||new URL(page.url()).searchParams.get('tab')!=='work')await go(ch,'work');
   });
  }
 }
}
