 if(tab==='output'){const attr={1:'r',2:'q',3:'d',4:'l',5:'a',6:'t',7:'tr',8:'i',9:'sec',10:'rt',11:'rv'}[ch];await pressIf('[data-'+attr+'-action="export-json"]');if(ch<11&&await pressIf('[data-'+attr+'-action="handoff"]')){let dialog=page.locator('dialog[open]');if(await dialog.count()){let acknowledge=dialog.locator('[name=acknowledge]');if(await acknowledge.count())await acknowledge.check();let submit=dialog.locator('[type=submit]');if(await submit.count()){await submit.click();await dialog.waitFor({state:'detached'});await networkQuiet();}else result.actions.push({type:'blocked-handoff',chapter:ch,detail:await dialog.innerText()});await closeDialogs();}}}
