function controlKey(c,chapter,tab){const attrs=Object.entries(c.attributes||{}).filter(([k])=>!['data-header-focus'].includes(k)).sort(([a],[b])=>a.localeCompare(b));return [chapter||'',tab||'',c.tag||'BUTTON',attrs.length?JSON.stringify(attrs):c.id?'#'+c.id:c.label].join('|');}
async function writeCoverage(){
 const observed=new Map();for(const surface of [...result.surfaces,...result.modelViews.map(s=>({...s,tab:'model'})),...result.observedButtons])for(const c of surface.controls||[])if(c.tag==='BUTTON'&&c.visible){const key=controlKey(c,String(surface.chapter),surface.tab);if(!observed.has(key))observed.set(key,{chapter:surface.chapter,tab:surface.tab,label:c.label,id:c.id,attributes:c.attributes,disabled:c.disabled,key});}
 const clicked=new Set(result.interactionEvents.filter(e=>e.tag==='BUTTON').map(e=>controlKey(e,e.chapter,e.tab)));const manifest=[...observed.values()].map(c=>({...c,exercised:clicked.has(c.key),status:clicked.has(c.key)?'clicked':c.disabled?'disabled in synthetic fixture':'not exercised',reason:clicked.has(c.key)?'Real browser click captured':c.disabled?'The current authored project does not enable this action':/retire|remove|delete|supersede/i.test(c.label)?'Destructive lifecycle alternative not completed in this pass':/Sol|provider/i.test(c.label)?'Provider-dependent or additional assistant workflow not completed':'Additional conditional workflow or shell control outside exercised path'}));
 result.coverage={surfaces:result.surfaces.length,expectedSurfaces:['authored','verify','discover','review'].includes(mode)?44:null,modelViews:result.modelViews.length,clickEvents:result.interactionEvents.length,uniqueObservedButtons:manifest.length,clickedObservedButtons:manifest.filter(c=>c.exercised).length,disabledObservedButtons:manifest.filter(c=>!c.exercised&&c.disabled).length,remainingEnabledButtons:manifest.filter(c=>!c.exercised&&!c.disabled).length,claim:'Observed button coverage only. This is not exhaustive proof of every conditional button or every business outcome.'};
 await writeFile(path.join(dir,'button-coverage.json'),JSON.stringify({summary:result.coverage,buttons:manifest},null,2));
 const behavior=(c,ch,tab)=>{
  const attributes=Object.entries(c.attributes||{}).filter(([k])=>!['data-header-focus'].includes(k)).map(([k,v])=>[k,/^(?:data-[a-z]+-(?:id|object|requirement|field|option)|data-sel|data-select|data-card)$/.test(k)?String(v).replace(/([A-Za-z][A-Za-z-]*-)[0-9]+/g,'$1*'):String(v).replace(/\b((?:REQ|QD|ADR|ALT|LR|APP|TN|CAP|TR|DAT|DF|IF|THR|CTL|ENV|RUN|ZONE|GRP|SCP|OUT|JRN)-)[0-9]+\b/gi,'$1*')]).sort(([a],[b])=>a.localeCompare(b));
  return [String(ch||''),tab||'',c.tag||'BUTTON',attributes.length?JSON.stringify(attributes):c.id?'#'+c.id:String(c.label||'').replace(/\b[0-9]+\b/g,'#')].join('|');
 };
 const evidence=[result];for(const directory of [priorDir,process.env.AIW_ADDITIONAL_EVIDENCE||''].filter(Boolean)){try{evidence.push(JSON.parse(await readFile(path.join(directory,'results.json'),'utf8')));}catch{/* no earlier evidence in that directory */}}
 const functions=new Map(),functionClicks=new Set();for(const run of evidence){for(const event of run.interactionEvents||[])if(event.tag==='BUTTON')functionClicks.add(behavior(event,event.chapter,event.tab));for(const surface of [...run.surfaces||[],...(run.modelViews||[]).map(x=>({...x,tab:'model'})),...run.observedButtons||[]])for(const c of surface.controls||[])if(c.tag==='BUTTON'&&c.visible){const key=behavior(c,surface.chapter,surface.tab);let item=functions.get(key);if(!item){item={chapter:Number(surface.chapter),tab:surface.tab,key,label:c.label,attributes:c.attributes,instances:0,enabledObserved:false,disabledObserved:false};functions.set(key,item);}item.instances++;item.enabledObserved||=!c.disabled;item.disabledObserved||=c.disabled;}}
 const functional=[...functions.values()].map(x=>({...x,exercised:functionClicks.has(x.key),status:functionClicks.has(x.key)?'clicked':x.enabledObserved?'not exercised':'disabled'}));result.functionalCoverage={evidenceRuns:evidence.map(x=>x.dir),functionsObserved:functional.length,functionsClicked:functional.filter(x=>x.exercised).length,enabledFunctionsRemaining:functional.filter(x=>!x.exercised&&x.enabledObserved).length,disabledFunctions:functional.filter(x=>!x.exercised&&!x.enabledObserved).length};
 await writeFile(path.join(dir,'functional-action-coverage.json'),JSON.stringify({summary:result.functionalCoverage,actions:functional},null,2));
 const fcols=['chapter','tab','label','status','instances','enabledObserved','disabledObserved','attributes'];await writeFile(path.join(dir,'functional-action-coverage.csv'),[fcols.join(','),...functional.map(x=>fcols.map(k=>'"'+String(k==='attributes'?JSON.stringify(x[k]):x[k]??'').replaceAll('"','""')+'"').join(','))].join('\n'));

 const cols=['chapter','tab','label','status','reason','attributes'];const csv=[cols.join(','),...manifest.map(x=>cols.map(k=>'"'+String(k==='attributes'?JSON.stringify(x[k]):x[k]??'').replaceAll('"','""')+'"').join(','))].join('\n');await writeFile(path.join(dir,'button-coverage.csv'),csv);
}
